import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Contraction-ordering ladder — does greedy lose, and what closes it?","description":"","frontmatter":{"title":"Contraction-ordering ladder — does greedy lose, and what closes it?","type":"retro","date":"2026-10-14T00:00:00.000Z"},"headers":[],"relativePath":"graphopt/project/retros/contraction-ladder.md","filePath":"vendored/graphopt/project/retros/contraction-ladder.md"}`),a={name:`graphopt/project/retros/contraction-ladder.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="contraction-ordering-ladder-—-does-greedy-lose-and-what-closes-it" tabindex="-1">Contraction-ordering ladder — does greedy lose, and what closes it? <a class="header-anchor" href="#contraction-ordering-ladder-—-does-greedy-lose-and-what-closes-it" aria-label="Permalink to “Contraction-ordering ladder — does greedy lose, and what closes it?”">​</a></h1><p>Plan 0016 stage 7 (ADR 0003, the EVALUATION dimension). The contraction-ordering precondition (<code>contraction-precondition.md</code>) established that the one-step greedy cost-model oracle is <em>provably</em> suboptimal on matrix chains and general tensor networks. This retro scores the players on a <strong>hard-instance set</strong>, against the exact DP optimum, as a bench suite (<code>bench/suites/evaluation/contraction_ladder.py</code>).</p><p>The question it answers:</p><blockquote><p>Does greedy lose on contraction ordering, and does anything close the gap to the exact optimum?</p></blockquote><p><strong>Yes, greedy loses; yes, equality saturation closes it exactly.</strong> The consequence is the honest one: on this space a learned policy has <strong>no quality headroom</strong> above the non-learned players — the residual headroom is <em>search cost</em>, not quality.</p><p>Reproduce: <code>python -m bench run contraction_ladder</code> (~18 s, CPU-only, seeded; <code>--quick</code> shrinks to ~7 s). Direct: <code>python -m bench.suites.evaluation.contraction_ladder</code>.</p><h2 id="the-hard-instance-set" tabindex="-1">The hard-instance set <a class="header-anchor" href="#the-hard-instance-set" aria-label="Permalink to “The hard-instance set”">​</a></h2><p>Both families are <strong>seeded random draws from the measured distribution</strong>, not hand-picked winners — ties are kept and counted.</p><ul><li><strong>Matrix chains</strong> — 60 draws, 4–8 matrices, dims 1..40 (seed 0). This is the hard regime (2–3-matrix chains are trivially optimal).</li><li><strong>General tensor networks</strong> — 60 draws, 3–6 tensors, mixed ranks over 3–7 shared indices, sizes 2–12 (seed 1).</li></ul><p>The subset DP is <strong>re-validated inside the suite</strong> against exhaustive enumeration (40 random cases, 0 mismatches) so the &quot;optimal&quot; the ladder scores against is trustworthy.</p><h2 id="the-ladder" tabindex="-1">The ladder <a class="header-anchor" href="#the-ladder" aria-label="Permalink to “The ladder”">​</a></h2><p>Players (chains — the priced e-graph rule space over <code>Var</code> leaves, <code>flops_cost</code> units):</p><ul><li><code>greedy-1step</code> — the one-step rule-delta oracle (<code>catopt_core.trajectories.rule_samples</code>): apply the largest-delta rule once.</li><li><code>greedy-episode</code> — the RL script&#39;s greedy player (horizon 6, patience 2).</li><li><code>saturate</code> — full equality saturation: the ceiling this rule set can reach.</li><li><code>optimal</code> — the exact <code>O(n³)</code> interval DP (<code>2 ×</code> the scalar-multiplication DP; <code>flops_cost</code> prices a matmul at <code>2·M·N·K</code>).</li></ul><h3 id="chain-ladder-n-60" tabindex="-1">Chain ladder (n=60) <a class="header-anchor" href="#chain-ladder-n-60" aria-label="Permalink to “Chain ladder (n=60)”">​</a></h3><table tabindex="0"><thead><tr><th>player</th><th>mean ratio</th><th>median</th><th>% at optimum</th><th>worst</th><th>mean rank</th></tr></thead><tbody><tr><td>greedy-1step</td><td>1.276</td><td>1.000</td><td>63 %</td><td><strong>4.10×</strong></td><td>3.04</td></tr><tr><td>greedy-episode</td><td>1.000</td><td>1.000</td><td>98 %</td><td>1.007×</td><td>2.34</td></tr><tr><td>saturate</td><td>1.000</td><td>1.000</td><td><strong>100 %</strong></td><td>1.000×</td><td>2.31</td></tr><tr><td>optimal</td><td>1.000</td><td>1.000</td><td>100 %</td><td>1.000×</td><td>2.31</td></tr></tbody></table><p>Ties the optimum: <code>saturate</code> 60/60, <code>greedy-episode</code> 59/60, <code>greedy-1step</code> 38/60. Ranks are <strong>shared on ties</strong> (all four tie on 38 instances → each scores rank 2.5), which is why the top three share a mean rank of 2.31 — the ratio / <code>%opt</code> / worst columns are the meaningful ones.</p><h3 id="network-ladder-n-60" tabindex="-1">Network ladder (n=60) <a class="header-anchor" href="#network-ladder-n-60" aria-label="Permalink to “Network ladder (n=60)”">​</a></h3><p>There is no e-graph spelling of a general tensor network (the precondition retro&#39;s documented limitation), so the priced players do not apply; the net family measures the textbook baseline directly (<code>greedy-classic</code> = contract the cheapest pair; <code>optimal</code> = the subset DP).</p><table tabindex="0"><thead><tr><th>player</th><th>mean ratio</th><th>median</th><th>% at optimum</th><th>worst</th><th>mean rank</th></tr></thead><tbody><tr><td>greedy-classic</td><td>1.574</td><td>1.047</td><td>33 %</td><td><strong>5.50×</strong></td><td>1.83</td></tr><tr><td>optimal</td><td>1.000</td><td>1.000</td><td>100 %</td><td>1.000×</td><td>1.17</td></tr></tbody></table><p>Ties the optimum: <code>greedy-classic</code> 20/60.</p><h2 id="headline-finding" tabindex="-1">Headline finding <a class="header-anchor" href="#headline-finding" aria-label="Permalink to “Headline finding”">​</a></h2><ul><li><strong><code>saturate == optimal</code> on every chain (60/60).</strong> The priced e-graph rule space is <em>exact</em> here: <code>assoc_matmul</code> closes the full bracketing space, so saturation reaches the DP optimum with no gap. This is a <strong>WIN</strong> for the rule set, and it is the answer to &quot;does anything close the gap&quot; — yes, exactly.</li><li><strong>Greedy loses.</strong> The one-step oracle (<code>greedy-1step</code>) is at the optimum on only 38/60 chains (<strong>loses 37 %</strong>, worst <strong>4.1×</strong>); the multi-step episode (<code>greedy-episode</code>, h6/p2) nearly closes it — loses <strong>1.7 %</strong> (1/60), worst 1.007×; the classic network greedy loses <strong>67 %</strong> (40/60), worst <strong>5.5×</strong>.</li></ul><p>So: greedy <strong>does</strong> lose, most sharply the one-step oracle and the classic network greedy; and <strong>saturation closes the gap exactly</strong> on every chain.</p><h3 id="consequence-for-a-learned-policy-—-search-cost-not-quality" tabindex="-1">Consequence for a learned policy — search cost, not quality <a class="header-anchor" href="#consequence-for-a-learned-policy-—-search-cost-not-quality" aria-label="Permalink to “Consequence for a learned policy — search cost, not quality”">​</a></h3><p>Because <code>saturate</code> already ties the DP optimum on every chain, a learned <code>Policy</code> <strong>cannot beat the non-learned players on quality</strong> in this space — there is nothing left to win. Any remaining headroom is <strong>search cost</strong>: reaching the optimum in fewer rule applications than saturation&#39;s fixed point.</p><p>That headroom is <em>small at these sizes</em>, measured honestly (best-of-3 wall time per instance, mean / max ms):</p><table tabindex="0"><thead><tr><th>player</th><th>chain mean</th><th>chain max</th><th>net mean</th></tr></thead><tbody><tr><td>greedy-1step</td><td>13.9</td><td>20.1</td><td>—</td></tr><tr><td>greedy-episode</td><td>44.6</td><td>83.7</td><td>—</td></tr><tr><td>saturate</td><td>13.5</td><td>52.2</td><td>—</td></tr><tr><td>optimal</td><td>0.01</td><td>0.02</td><td>0.12</td></tr><tr><td>greedy-classic</td><td>—</td><td>—</td><td>0.01</td></tr></tbody></table><p>Saturation on a 4–8-matrix chain is already <em>cheaper</em> than the greedy episode (it stops at the fixed point; the episode evaluates all 51 rules per step, up to 6 steps). A policy could only pay off where saturation <strong>blows up</strong> — the exact-saturation fragmentation at large chain depth (<code>search_efficiency</code>). That is the honest scope of the learned-policy headroom, and it is a search-cost question.</p><h2 id="the-seam-for-a-learned-policy" tabindex="-1">The seam for a learned <code>Policy</code> <a class="header-anchor" href="#the-seam-for-a-learned-policy" aria-label="Permalink to “The seam for a learned Policy”">​</a></h2><p>The suite scores the non-learned players only and does not depend on the RL reward (being reworked elsewhere). A learned player drops into <code>_chain_players(rules)</code> as one more entry:</p><div class="language-python"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">learned</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> lambda</span><span style="--shiki-dark:#FFFFFF;--shiki-dark-font-style:italic;--shiki-light:#24292E;--shiki-light-font-style:inherit;"> dims</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> _learned_episode</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">dims</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> rules</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> policy</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">))</span></span></code></pre></div><p>It drives the same <code>catopt_core.search_env.SearchEnv</code> episode, so it returns a <code>flops_cost</code> in the same units and the ratio/rank statistics need no other change.</p><h2 id="honest-limitations" tabindex="-1">Honest limitations <a class="header-anchor" href="#honest-limitations" aria-label="Permalink to “Honest limitations”">​</a></h2><ul><li><strong>Ranks are shared on ties.</strong> The chain ladder&#39;s top three share a mean rank of 2.31 because they tie on most instances; read the ratio and <code>%opt</code> columns, not the rank.</li><li><strong>The net family has no priced player.</strong> <code>greedy-classic</code> vs the subset DP is the only ladder there; there is no catopt e-graph spelling of a general tensor network today.</li><li><strong>One cost model.</strong> All chain numbers use <code>flops_cost</code> (the <code>SearchEnv</code> default). A different model could shift the exact ratios, though the bracketings differ in FLOPs, not kernel count.</li><li><strong>Saturation is exact <em>here</em>.</strong> Only because <code>assoc_matmul</code> closes the whole bracketing space; under a budget-truncated saturation (<code>rule_budgets</code>, <code>stop=&quot;improving&quot;</code>) the &quot;optimum&quot; is only the reachable one.</li><li><strong>Greedy is <em>a</em> baseline.</strong> The one-step oracle is the plan&#39;s baseline; a stronger classical baseline (e.g. a beam over contraction moves) would shrink the measured headroom.</li></ul><h2 id="reproduce" tabindex="-1">Reproduce <a class="header-anchor" href="#reproduce" aria-label="Permalink to “Reproduce”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">python</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> -m</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> bench</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> contraction_ladder</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">          #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> full ladder + findings</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">python</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> -m</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> bench</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> contraction_ladder</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --quick</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">   #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> ~7 s</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">python</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> -m</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> bench.suites.evaluation.contraction_ladder</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --no-artifacts</span></span></code></pre></div>`,36)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};